using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Returns an HTTP URL which can be used to automatically authorize the current user on a website after clicking an HTTP link.
    /// Use the method getExternalLinkInfo to find whether a prior user confirmation is needed. May return an empty link if just a toast about successful login has to be shown
    /// </summary>
    public Task<TdLib.TdApi.Objects.HttpUrl> GetExternalLinkAsync(string link = default, bool allowWriteAccess = default)
    {

           using var activity =  StartCallActivity("GetExternalLinkAsync", typeof(GetExternalLink).FullName ?? "GetExternalLinkAsync");

           try
           {
             return client.GetExternalLinkAsync(link, allowWriteAccess);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
// REUSE-IgnoreEnd